int sc_pkcs15emu_object_add(sc_pkcs15_card_t *p15card, unsigned int type,
        const sc_pkcs15_object_t *in_obj, const void *data)
{
        sc_pkcs15_object_t *obj;
        unsigned int    df_type;
        size_t          data_len;

        obj = calloc(1, sizeof(*obj));
        if (!obj)
                return SC_ERROR_OUT_OF_MEMORY;
        memcpy(obj, in_obj, sizeof(*obj));
        obj->type  = type;

        switch (type & SC_PKCS15_TYPE_CLASS_MASK) {
        case SC_PKCS15_TYPE_AUTH:
                df_type  = SC_PKCS15_AODF;
                data_len = sizeof(struct sc_pkcs15_auth_info);
                break;
        case SC_PKCS15_TYPE_PRKEY:
                df_type  = SC_PKCS15_PRKDF;
                data_len = sizeof(struct sc_pkcs15_prkey_info);
                break;
        case SC_PKCS15_TYPE_PUBKEY:
                df_type = SC_PKCS15_PUKDF;
                data_len = sizeof(struct sc_pkcs15_pubkey_info);
                break;
        case SC_PKCS15_TYPE_CERT:
                df_type = SC_PKCS15_CDF;
                data_len = sizeof(struct sc_pkcs15_cert_info);
                break;
        case SC_PKCS15_TYPE_DATA_OBJECT:
                df_type = SC_PKCS15_DODF;
                data_len = sizeof(struct sc_pkcs15_data_info);
                break;
        default:
                sc_log(p15card->card->ctx, "Unknown PKCS15 object type %d", type);
                free(obj);
                return SC_ERROR_INVALID_ARGUMENTS;
        }

        obj->data = calloc(1, data_len);
        if (obj->data == NULL) {
                free(obj);
                return SC_ERROR_OUT_OF_MEMORY;
        }
        memcpy(obj->data, data, data_len);

        obj->df = sc_pkcs15emu_get_df(p15card, df_type);
        sc_pkcs15_add_object(p15card, obj);

        return SC_SUCCESS;
}

sc_pkcs15_add_object(struct sc_pkcs15_card *p15card, struct sc_pkcs15_object *obj)
{
        struct sc_pkcs15_object *p = p15card->obj_list;

        if (!obj)
                return 0;
        obj->next = obj->prev = NULL;
        if (p15card->obj_list == NULL) {
                p15card->obj_list = obj;
                return 0;
        }
        while (p->next != NULL)
                p = p->next;
        p->next = obj;
        obj->prev = p;

        return 0;
}


void
sc_pkcs15_remove_object(struct sc_pkcs15_card *p15card, struct sc_pkcs15_object *obj)
{
        if (!obj)
                return;
        else if (obj->prev == NULL)
                p15card->obj_list = obj->next;
        else
                obj->prev->next = obj->next;
        if (obj->next != NULL)
                obj->next->prev = obj->prev;
}


static void
sc_pkcs15_remove_objects(struct sc_pkcs15_card *p15card)
{
        struct sc_pkcs15_object *cur = NULL, *next = NULL;

        if (!p15card || !p15card->obj_list)
                return;
        for (cur = p15card->obj_list; cur; cur = next)   {
                next = cur->next;
                sc_pkcs15_free_object(cur);
        }

        p15card->obj_list = NULL;
}


